void Solver::bump_var(int var, double coeff) {
    double bumpAmount = var_inc * coeff;
    activity[var] += bumpAmount;

    if (activity[var] > 1e100) {
        double scaleFactor = 1e-100;
        for (int i = 1; i <= vars; i++) {
            activity[i] *= scaleFactor;
        }
        var_inc *= scaleFactor;
    }

    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
